/* eslint-disable @typescript-eslint/no-explicit-any */
import { Accessor, createRoot, onCleanup } from "solid-js";

export enum ModelLifecycle {
	/** A single model will be created, shared and persisted */
	Singleton,
	/** A single model will be created at any given time and shared. It will be destroyed when it is not in active use. */
	SharedInstance,
	/** A new model will be created every time get is called on the model */
	PerInstance,
}

interface InternalModelFactory<T extends Record<string, any>> {
	name: string;
	get: Accessor<T>;
	lifecycle: ModelLifecycle;
	overridePriority: number;
	instance: T | undefined;
	factory: Accessor<T>;
	refCount: number | undefined;
}

export interface ModelFactory<T extends Record<string, any>> {
	readonly get: Accessor<T>;
}

/**
 * The model Registry
 *
 * The model registry can be used to register and generate overridable models
 *
 * To generate a model override, define a new model with the same name and higher priority:
 * ```ts
 * export const OriginalModel = ModelRegistry.register("ModelName", ModelLifecycle.Singleton, () => modelInstance);
 * ...
 * export const OverrideModel = ModelRegistry.register("ModelName",  ModelLifecycle.Singleton, () => overrideInstance, 1);
 * ```
 * In the example above, both OriginalModel and OverrideModel will create an OverrideComponent when called.
 */
class ModelRegistryImpl {
	modelFactories = new Map<string, InternalModelFactory<never>>();
	private rootDisposeFn: (() => void) | undefined;
	private isInitialized = false;

	constructor() {
		engine.whenReady.then(() => {
			createRoot((dispose) => {
				this.rootDisposeFn = dispose;

				// Resolve registered models
				for (const modelFactory of this.modelFactories.values()) {
					this.resolveModel(modelFactory);
				}

				this.isInitialized = true;
			});
		});
	}

	/**
	 * Registers a model with the model registry.
	 * Models can be overriden (for example, by mods) by setting a higher priority in options
	 * See {@link ModelRegistryImpl} for more info
	 * ```ts
	 * export const ExampleModel = ModelRegistry.register("ExampleModel", ModelLifecycle.PerInstance, createExampleModel), overridePriority: 0);
	 * ```
	 * @param name The name of the model - only used for registration and overrides
	 * @param lifecycle Is the model a singleton or is it a per instance model?
	 * @param factory The model factory function
	 * @param overridePriority The model registered with the highest override priority will be used. Default: 0
	 *
	 * @returns The registered overridable component
	 */
	public register<T extends Record<string, any>>(
		name: string,
		lifecycle: ModelLifecycle,
		factory: () => T,
		overridePriority?: number,
	): ModelFactory<T> {
		let modelFactory = this.modelFactories.get(name);

		overridePriority ??= 0;
		if (modelFactory) {
			if (modelFactory.overridePriority < overridePriority) {
				modelFactory.overridePriority = overridePriority;
				modelFactory = this.updateModel(modelFactory, name, lifecycle, factory as Accessor<never>);
			}
		} else {
			const partialFactory = {
				name,
				overridePriority,
			};

			modelFactory = this.updateModel(partialFactory, name, lifecycle, factory as Accessor<never>);
			this.modelFactories.set(name, modelFactory);
		}

		return modelFactory as ModelFactory<T>;
	}

	/**
	 * Gets a registered model from the model registry.
	 * Will return a model that points the model factory with the highest override priority.
	 * @param name The name of the model to get
	 * @returns The registered model or undefined if no registration was not found
	 */
	public get<T extends Record<string, any>>(name: string) {
		return this.modelFactories.get(name) as ModelFactory<T> | undefined;
	}

	/**
	 * Cleans up the model registry solid root
	 */
	public destroy() {
		this.rootDisposeFn?.();
		this.modelFactories.clear();
	}

	private updateModel(
		modelFactory: any,
		name: string,
		lifecycle: ModelLifecycle,
		factory: Accessor<never>,
	): InternalModelFactory<never> {
		modelFactory.lifecycle = lifecycle;
		modelFactory.instance = undefined;
		modelFactory.factory = factory;
		modelFactory.get = () => {
			throw new Error(`Model Registry - Unable to resolve model "${name}" before engine ready!`);
		};

		if (this.isInitialized) {
			this.resolveModel(modelFactory);
		}

		return modelFactory;
	}

	private resolveModel(model: InternalModelFactory<never>) {
		switch (model.lifecycle) {
			case ModelLifecycle.PerInstance:
				model.get = model.factory;
				break;

			case ModelLifecycle.Singleton:
				model.instance = model.factory?.();
				model.get = () => model.instance as never;
				break;

			case ModelLifecycle.SharedInstance:
				model.refCount = 0;
				model.get = () => {
					if (model.instance == undefined) {
						model.instance = model.factory?.();
					}

					model.refCount!++;

					onCleanup(() => {
						model.refCount!--;
						if (model.refCount! <= 0) {
							model.instance = undefined;
							model.refCount = 0;
						}
					});

					return model.instance as never;
				};
				break;
		}
	}
}

export const ModelRegistry = new ModelRegistryImpl();
